const row = $input.first().json || {};
const s = row.summary || {};
const api = s.api || { total: 0, errors: 0, avg_ms: 0, p95_ms: 0 };
const routes = Array.isArray(s.routes) ? s.routes : [];
const llm = Array.isArray(s.llm) ? s.llm : [];
const errors = Array.isArray(s.errors) ? s.errors : [];
const n8n = s.n8n || { total: 0, success: 0, error: 0, avg_ms: 0 };

const now = new Date();
const dateStr = new Intl.DateTimeFormat('en-CA', {
  timeZone: 'America/Sao_Paulo',
  year: 'numeric',
  month: '2-digit',
  day: '2-digit',
}).format(now);

const filename = `observability-${dateStr}.md`;
const totalErrors = errors.reduce((acc, item) => acc + Number(item.total || 0), 0);

const routeRows = routes.length
  ? routes.map(r => `| \`${r.route}\` | ${r.hits} | ${r.errors} | ${r.avg_ms} ms |`).join('\n')
  : '| _(sem chamadas nas últimas 24h)_ | 0 | 0 | 0 ms |';

const llmRows = llm.length
  ? llm.map(l => `| \`${l.model}\` | ${l.calls} | ${l.errors} | ${l.avg_ms} ms |`).join('\n')
  : '| _(sem chamadas LLM registradas)_ | 0 | 0 | 0 ms |';

const errRows = errors.length
  ? errors.map(e => `| \`${e.source}\` | ${e.total} | ${e.last_seen} |`).join('\n')
  : '| _(nenhum erro nas últimas 24h)_ | 0 | - |';

const markdown = `---
source: usami-observability
kind: observability-daily
date: ${dateStr}
created_at: ${now.toISOString()}
api_calls: ${api.total || 0}
api_errors: ${api.errors || 0}
n8n_executions: ${n8n.total || 0}
n8n_errors: ${n8n.error || 0}
---

# 📊 Observabilidade Usami — ${dateStr}

## Resumo das últimas 24h
- **Eventos API / LLM / Tools:** ${api.total || 0} (erros/4xx+: ${api.errors || 0})
- **Latência API:** média ${api.avg_ms || 0} ms | p95 ${api.p95_ms || 0} ms
- **Execuções n8n:** ${n8n.total || 0} (sucesso: ${n8n.success || 0}, erro: ${n8n.error || 0}, média: ${n8n.avg_ms || 0} ms)
- **Total de erros registrados:** ${totalErrors}

## Top Rotas HTTP (/api/*)
| Rota | Chamadas | Erros | Latência média |
|---|---:|---:|---:|
${routeRows}

## Chamadas LLM por Modelo
| Modelo | Chamadas | Erros | Latência média |
|---|---:|---:|---:|
${llmRows}

## Erros por Origem
| Origem | Total | Último registro |
|---|---:|---|
${errRows}

---
_Gerado automaticamente por Usami - Relatorio Observabilidade (agendado) em ${now.toISOString()}_.
`;

let envChannel = '';
try {
  envChannel = ($env && $env.DISCORD_OBS_SUMMARY_CHANNEL_ID) ? String($env.DISCORD_OBS_SUMMARY_CHANNEL_ID).trim() : '';
} catch {
  envChannel = '';
}
const hasSummaryChannel = Boolean(envChannel && !envChannel.startsWith('CONFIGURE_'));

const discordPayload = {
  embeds: [{
    title: `📊 Relatório Diário de Observabilidade — ${dateStr}`,
    description: `Nota salva no Obsidian: \`Inbox/Automations/${filename}\``,
    color: (Number(n8n.error || 0) > 0 || totalErrors > 0) ? 16753920 : 5763719,
    fields: [
      { name: 'API / LLM Eventos', value: `${api.total || 0} (${api.errors || 0} falhas)`, inline: true },
      { name: 'Latência (Média / p95)', value: `${api.avg_ms || 0} ms / ${api.p95_ms || 0} ms`, inline: true },
      { name: 'Execuções n8n', value: `${n8n.total || 0} total (${n8n.error || 0} erros)`, inline: true },
      { name: 'Erros Totais (24h)', value: String(totalErrors), inline: true }
    ],
    timestamp: now.toISOString()
  }]
};

return [{
  json: {
    dateStr,
    filename,
    markdown,
    obsSummaryChannelId: envChannel,
    hasSummaryChannel,
    discordPayload
  }
}];
